#!/usr/bin/env node
const OPTIONS = [
  {flag: '--input', arg: 'file', description: 'Read records from this CSV file'},
  {flag: '--output', arg: 'file', description: 'Write the converted records to this file'},
  {flag: '--verbose', description: 'Print progress to stderr'},
  {flag: '--dry-run', alias: '-n', description: 'Show what would be written without writing'},
];

function parse(argv) {
  const values = {};
  for (let i = 0; i < argv.length; i++) {
    const option = OPTIONS.find(o => o.flag === argv[i] || o.alias === argv[i]);
    if (!option) throw new Error('Unknown option ' + argv[i]);
    values[option.flag.slice(2)] = option.arg ? argv[++i] : true;
  }
  return values;
}

module.exports = {OPTIONS, parse};
if (require.main === module) console.log(JSON.stringify(parse(process.argv.slice(2))));

