const assert = require('node:assert/strict'); const fs = require('node:fs'); const crypto = require('node:crypto');
const sha = text => crypto.createHash('sha256').update(text).digest('hex');
assert.equal(sha(fs.readFileSync('cli.js')), '95dce3e02e05a90f0cf3fa29b5b37fecc6da8d1d2da8d026efee6bb6e351de09', 'cli.js changed');
const md = fs.readFileSync('README.md', 'utf8');
const start = md.indexOf('\n## Options\n'); const end = md.indexOf('\n## Examples\n');
assert.ok(start >= 0 && end > start, 'Options and Examples headings must stay in place');
assert.equal(sha(md.slice(0, start)), '07031f1b699457abc8b62ee78d5a50a8cc183634b15af21fccc9f94608941b29', 'README before the Options section changed');
assert.equal(sha(md.slice(end)), '4ccb1443ef7a16094e43da341369ad65147c720cec9f6a03bf34e62f2eb18669', 'README after the Options section changed');
const rows = md.slice(start, end).split('\n').filter(line => line.trim().startsWith('|'));
assert.ok(rows.length >= 3 && /^\|[\s:|-]+\|$/.test(rows[1].trim()), 'Options must stay a markdown table');
const body = rows.slice(2).map(row => row.replace(/`/g, ''));
const real = require('./cli').OPTIONS;
const flagOf = row => (row.match(/--[a-z][a-z-]*/) || [])[0];
assert.deepEqual(body.map(flagOf).sort(), real.map(o => o.flag).sort(), 'table flags differ from cli.js OPTIONS');
const shortAlias = /(^|[^\w-])-[a-z](?![\w-])/;
for (const option of real) {
  const row = body.find(r => flagOf(r) === option.flag);
  assert.ok(row.split('|').filter(cell => cell.trim()).length >= 2, option.flag + ' needs a description');
  if (option.alias) assert.ok(row.includes(option.alias), option.flag + ' must show alias ' + option.alias);
  else assert.ok(!shortAlias.test(row), option.flag + ' must not show an alias');
}
